import java.util.Scanner;

public class Main {
    static final long MODULUS_CONST = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p_value = scanner.nextInt();
        int k_value = scanner.nextInt();
        int cycle_count;

        if (k_value == 0) {
            cycle_count = p_value - 1;
        } else if (k_value == 1) {
            cycle_count = p_value;
        } else {
            cycle_count = 0;
            boolean[] visited = new boolean[p_value];
            for (int start = 1; start < p_value; start++) {
                if (!visited[start]) {
                    visited[start] = true;
                    cycle_count++;
                    long j = ((long) start * k_value) % p_value;
                    while (!visited[(int) j]) {
                        visited[(int) j] = true;
                        j = (j * k_value) % p_value;
                    }
                }
            }
        }

        long total_product = 1;
        for (int i = 0; i < cycle_count; i++) {
            total_product = (total_product * p_value) % MODULUS_CONST;
        }
        System.out.println(total_product);
        scanner.close();
    }
}

